import { CONSTANTS, layout_types } from 'src/constants';

export interface DocumentLayoutSelection {
  layoutType: string;
  // Empty = leave the caller's existing filter alone.
  filterStatus: string;
}

export function layoutTypeForDocumentStatus(
  status: string,
  approveBeforeExportV2 = false,
): DocumentLayoutSelection {
  if (status === CONSTANTS.validated_pending_approval) {
    return {
      layoutType: approveBeforeExportV2
        ? layout_types.approval_v2
        : layout_types.approval,
      filterStatus: '',
    };
  }

  if (status === CONSTANTS.in_review) {
    return {
      layoutType: layout_types.review,
      filterStatus: CONSTANTS.in_review,
    };
  }

  if (status === CONSTANTS.approved_pending_second_approval) {
    return {
      layoutType: layout_types.second_approval,
      filterStatus: CONSTANTS.approved_pending_second_approval,
    };
  }

  return { layoutType: layout_types.field_validation, filterStatus: '' };
}
